import XCTest

/// Playback against real files generated by the CI step "Generate the media matrix" (ffmpeg): H.264 in Matroska and AVI,
/// HEVC Main10 with HDR10 and HLG signalling, the same stream tagged hev1, and 8-bit HEVC.
///
/// What these tests establish: the right engine is chosen from facts the decoder reports, the file plays (the clock
/// advances) and the app reports the dynamic range that the file *signals*. What they cannot establish: how it looks.
/// The pictures are synthetic test patterns on a simulator without an HDR display; Dolby Vision cannot be produced here.
final class PlayerMatrixUITests: AetherUITestCase {
    private func play(_ title: String, headless: Bool = true) {
        launchWithFixtureAddon(extraArguments: headless ? ["-AETHER_UITEST_MPV_HEADLESS"] : [])
        openTitleViaSearch(title, expecting: title)
        startPlayback()
        waitUntil(60, "\(title): the playhead never advanced past 2 s") { (playbackSeconds() ?? 0) >= 2 }
        XCTAssertFalse(element("player.error").exists, "\(title): an error panel is showing")
    }

    private func openInfo() {
        if !element("player.more").exists {
            app.coordinate(withNormalizedOffset: CGVector(dx: 0.5, dy: 0.5)).tap()
        }
        XCTAssertTrue(element("player.more").waitForExistence(timeout: 10), "the player's menu is not reachable")
        element("player.more").tap()
        let info = app.buttons["Informazioni sulla sorgente"]
        XCTAssertTrue(info.waitForExistence(timeout: 10), "no info entry in the player menu")
        info.tap()
        XCTAssertTrue(element("info.engine").waitForExistence(timeout: 10), "the info sheet did not open")
    }

    private func value(_ id: String) -> String {
        let element = self.element(id)
        return element.exists ? element.label : ""
    }

    private func attach(_ name: String) {
        let rows = ["info.engine", "info.container", "info.video", "info.range", "info.decodable", "info.dv", "info.vo", "info.expected"]
            .map { "\($0): \(value($0))" }.joined(separator: "\n")
        let attachment = XCTAttachment(string: rows)
        attachment.name = name
        attachment.lifetime = .keepAlways
        add(attachment)
        print("MATRIX \(name)\n\(rows)")
    }

    func testH264InMatroskaPlaysThroughMPV() {
        play("Matrix H264 MKV")
        openInfo()
        attach("h264.mkv")
        XCTAssertTrue(value("info.engine").contains("MPV"), "MKV needs the MPV engine: \(value("info.engine"))")
        XCTAssertTrue(value("info.container").lowercased().contains("matroska"), "container: \(value("info.container"))")
        XCTAssertTrue(value("info.video").lowercased().contains("h264"), "video: \(value("info.video"))")
    }

    func testH264InAVIPlaysThroughMPV() {
        play("Matrix H264 AVI")
        openInfo()
        attach("h264.avi")
        XCTAssertTrue(value("info.engine").contains("MPV"), value("info.engine"))
        XCTAssertTrue(value("info.container").lowercased().contains("avi"), "container: \(value("info.container"))")
    }

    func testHDR10InMP4PlaysThroughAVPlayerAndIsReportedAsHDR10() {
        play("Matrix HDR10 MP4")
        openInfo()
        attach("hdr10.mp4")
        XCTAssertTrue(value("info.engine").contains("AVPlayer"), "an HEVC Main10 hvc1 MP4 belongs to AVPlayer: \(value("info.engine"))")
        XCTAssertTrue(value("info.range").contains("HDR10"), "signalled range: \(value("info.range"))")
        XCTAssertFalse(value("info.range").contains("Dolby"), "nothing in this file is Dolby Vision")
    }

    func testHLGInMP4IsReportedAsHLG() {
        play("Matrix HLG MP4")
        openInfo()
        attach("hlg.mp4")
        XCTAssertTrue(value("info.engine").contains("AVPlayer"), value("info.engine"))
        XCTAssertTrue(value("info.range").contains("HLG"), "signalled range: \(value("info.range"))")
    }

    func testSDRHEVCIsNotReportedAsHDR() {
        play("Matrix SDR HEVC MP4")
        openInfo()
        attach("sdr-hevc.mp4")
        let range = value("info.range")
        XCTAssertFalse(range.contains("HDR10") || range.contains("HLG") || range.contains("Dolby"), "an SDR file must not be labelled HDR: \(range)")
    }

    func testHDR10InMatroskaIsReadByMPVAsHDR10() {
        play("Matrix HDR10 MKV")
        openInfo()
        attach("hdr10.mkv")
        XCTAssertTrue(value("info.engine").contains("MPV"), value("info.engine"))
        XCTAssertTrue(value("info.range").contains("HDR10"), "range reported by mpv: \(value("info.range"))")
    }

    /// The hev1 tag: whichever engine ends up playing it, the choice must agree with what the platform reported.
    func testHEV1TaggedHEVCPlaysAndTheEngineChoiceFollowsTheFacts() {
        play("Matrix HDR10 HEV1")
        openInfo()
        attach("hdr10-hev1.mp4")
        let engine = value("info.engine")
        let decodable = value("info.decodable")
        if engine.contains("AVPlayer") {
            XCTAssertFalse(decodable.contains("No"), "AVPlayer must not be playing a track iOS says it cannot decode: \(decodable)")
        } else {
            XCTAssertTrue(engine.contains("MPV"), engine)
        }
    }

    /// Needs a working Metal/Vulkan device: on a simulator without GPU access this is expected to fail, and the failure
    /// message says so. It is the only test that looks at the real video output of the MPV engine.
    func testMPVVideoOutputInitialisesOnTheSimulator() {
        play("Matrix H264 MKV", headless: false)
        openInfo()
        attach("h264.mkv (real video output)")
        XCTAssertTrue(value("info.vo").contains("Attiva"), "mpv video output: \(value("info.vo"))")
    }
}
